use crate::reach_inc::reach_oracle;
use crate::store_db::StoreDb;
use std::collections::HashSet;
pub struct SqliteReachDRed { db:StoreDb, roots:Vec<i64>, edges:HashSet<(i64,i64)>, stmts:u64, rounds:u64 }
impl Default for SqliteReachDRed {fn default()->Self{Self::new()}}
impl SqliteReachDRed {pub fn new()->Self{let db=StoreDb::memory();db.exec("CREATE TABLE edge(u INTEGER NOT NULL,v INTEGER NOT NULL,PRIMARY KEY(u,v)) WITHOUT ROWID");Self{db,roots:Vec::new(),edges:HashSet::new(),stmts:0,rounds:0}}pub fn setup(&mut self,roots:&[i64],edges:&[(i64,i64)]){self.roots=roots.to_vec();self.edges=edges.iter().copied().collect();if !edges.is_empty(){self.db.exec(format!("INSERT INTO edge(u,v) VALUES {}",edges.iter().map(|(u,v)|format!("({u},{v})")).collect::<Vec<_>>().join(",")));}self.stmts+=1;}pub fn add_batch(&mut self,adds:&[(i64,i64)]){for &(u,v) in adds{self.edges.insert((u,v));}if !adds.is_empty(){self.db.exec(format!("INSERT OR IGNORE INTO edge(u,v) VALUES {}",adds.iter().map(|(u,v)|format!("({u},{v})")).collect::<Vec<_>>().join(",")));self.stmts+=1;}}pub fn del_batch(&mut self,dels:&[(i64,i64)]){for e in dels{self.edges.remove(e);}if !dels.is_empty(){self.db.exec(format!("DELETE FROM edge WHERE (u,v) IN ({})",dels.iter().map(|(u,v)|format!("({u},{v})")).collect::<Vec<_>>().join(",")));self.stmts+=1;}}pub fn reachable(&self)->(i64,u64){reach_oracle(&self.roots,&self.edges)}pub fn statements(&self)->u64{self.stmts}pub fn rounds(&self)->u64{self.rounds}}
